import{_ as t,c as a,o,ag as r}from"./chunks/framework.Ci10AEOF.js";const p=JSON.parse('{"title":"Upgrade Guide","description":"How to upgrade to a newer version","frontmatter":{"title":"Upgrade Guide","description":"How to upgrade to a newer version"},"headers":[],"relativePath":"engine/upgrade_guide.md","filePath":"engine/upgrade_guide.md","lastUpdated":1793057853000}'),n={name:"engine/upgrade_guide.md"};function s(i,e,d,l,c,h){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h1><p>To move an existing Mirth Connect server onto OIE, see <a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a>.</p><h2 id="before-you-upgrade" tabindex="-1">Before you upgrade <a class="header-anchor" href="#before-you-upgrade" aria-label="Permalink to &quot;Before you upgrade&quot;">​</a></h2><h3 id="_1-back-up-everything" tabindex="-1">1. Back up everything <a class="header-anchor" href="#_1-back-up-everything" aria-label="Permalink to &quot;1. Back up everything&quot;">​</a></h3><p>Back up:</p><ul><li><p><strong>Server configuration</strong>: Export via the Administrator (<strong>Settings &gt; Server Tab &gt; Server Tasks &gt; Backup Config</strong>) or via the CLI (<code>exportcfg &quot;path&quot;</code>). The export holds channels, channel groups, tags and dependencies, code templates, alerts, global scripts, the configuration map, resources, server settings, and plugin properties.</p><blockquote><p><strong>Warning:</strong> The Server Configuration file does <strong>not</strong> include user accounts, events, or message/attachment data. Back those up separately if needed.</p></blockquote></li><li><p><strong>Database</strong>: If using the embedded Derby database, back up the <code>appdata/mirthdb</code> folder. If using an external database (PostgreSQL, MySQL, Oracle, SQL Server), create a backup using your database administration tool.</p></li><li><p><strong>Application data directory</strong> (<code>appdata/</code>): Holds the keystore, the server id, and the embedded Derby database</p></li><li><p><strong>Configuration files</strong> (<code>conf/</code>): Especially <code>mirth.properties</code> and any customized files</p></li><li><p><strong>Custom database driver entries</strong>: If you have added entries to <code>conf/dbdrivers.xml</code>, back up that file</p></li><li><p><strong>JVM parameters</strong>: If you have modified heap size or other JVM settings, back up all <code>*.vmoptions</code> files in the installation directory and in <code>conf/</code></p></li><li><p><strong>CLI configuration</strong>: If you have customized <code>conf/mirth-cli-config.properties</code>, back up that file</p></li><li><p><strong>Custom libraries</strong>: If you created a <code>custom-lib/</code> directory for your own JARs, back it up. The install does not create it. The launcher adds it to the server classpath only when <code>server.includecustomlib</code> is not <code>false</code>, and the shipped <code>mirth.properties</code> sets it to <code>false</code>. Channel scripts still load its JARs through the <strong>[Default Resource]</strong> in <strong>Settings &gt; Resources</strong>, whatever that setting says</p></li></ul><h3 id="_2-read-the-release-notes" tabindex="-1">2. Read the release notes <a class="header-anchor" href="#_2-read-the-release-notes" aria-label="Permalink to &quot;2. Read the release notes&quot;">​</a></h3><p>Read the release notes of every version after yours, up to and including the one you are installing, on the <a href="https://github.com/OpenIntegrationEngine/engine/releases" target="_blank" rel="noreferrer">Releases page</a>. Note each setting whose default changed and each key that was added: you merge them into your own configuration in <a href="#merging-your-configuration">Merging your configuration</a>. For 4.7.0 they are summarized in <a href="#upgrading-to-4-7-0">Upgrading to 4.7.0</a>.</p><h3 id="_3-plan-downtime" tabindex="-1">3. Plan downtime <a class="header-anchor" href="#_3-plan-downtime" aria-label="Permalink to &quot;3. Plan downtime&quot;">​</a></h3><p>Upgrading requires stopping the server.</p><h2 id="upgrade-process" tabindex="-1">Upgrade process <a class="header-anchor" href="#upgrade-process" aria-label="Permalink to &quot;Upgrade process&quot;">​</a></h2><h3 id="using-the-installer" tabindex="-1">Using the installer <a class="header-anchor" href="#using-the-installer" aria-label="Permalink to &quot;Using the installer&quot;">​</a></h3><ol><li>Exit the <strong>Administrator</strong> and stop the <strong>server service/daemon</strong></li><li>Run the new version&#39;s installer against the existing installation directory. Unattended on Linux: <code>sh oie_unix_&lt;version&gt;.sh -q -dir &lt;installation directory&gt;</code>. It removes the previous version and installs the new one</li><li>The installer keeps <code>appdata/</code> and leaves every file in <code>conf/</code> exactly as it was. None of the new version&#39;s configuration defaults are added; see <a href="#merging-your-configuration">Merging your configuration</a></li><li>The installer replaces <code>oieserver.vmoptions</code> and <code>oieservice.vmoptions</code> in the installation directory. Put options you added there back afterwards, or keep them in <code>conf/custom.vmoptions</code>, which both files include and which the installer keeps</li><li>Start the server. It runs any required database schema migration at startup and writes the new version into the <code>version</code> line of <code>conf/mirth.properties</code></li></ol><h3 id="using-pre-packaged-distributions" tabindex="-1">Using pre-packaged distributions <a class="header-anchor" href="#using-pre-packaged-distributions" aria-label="Permalink to &quot;Using pre-packaged distributions&quot;">​</a></h3><p>For archive-based installations (ZIP/TAR.GZ):</p><ol><li>Exit the <strong>Administrator</strong> and stop the <strong>server service/daemon</strong></li><li>Back up the entire installation directory</li><li>Extract the new version to a new location</li><li>Copy your <code>appdata/</code> directory to the new installation</li><li>Merge your configuration into the new installation&#39;s <code>conf/</code>; see <a href="#merging-your-configuration">Merging your configuration</a></li><li>Copy <code>custom-lib/</code> if you created one, and any extension you installed yourself from <code>extensions/</code>. Each extension needs a build for the new version; see <a href="./plugins.html#plugin-compatibility-and-version-requirements">Plugin compatibility and version requirements</a></li><li>Start the server from the new installation directory. It runs any required database schema migration at startup and writes the new version into the <code>version</code> line of <code>conf/mirth.properties</code></li></ol><h3 id="merging-your-configuration" tabindex="-1">Merging your configuration <a class="header-anchor" href="#merging-your-configuration" aria-label="Permalink to &quot;Merging your configuration&quot;">​</a></h3><p>Neither upgrade path updates your configuration. The installer keeps your <code>conf/</code> unchanged, and an archive upgrade uses the files you bring. Merge with the release notes in hand:</p><ol><li>Compare your <code>conf/</code> with the new version&#39;s, for example <code>diff -r &lt;old installation&gt;/conf &lt;new installation&gt;/conf</code></li><li>Start from your own <code>mirth.properties</code>, not the new one. A server that has run has written values into it that belong to your data: the keystore passwords generated at its first start (<code>keystore.storepass</code> and <code>keystore.keypass</code>), which open <code>appdata/keystore.jks</code>, and its <code>database.url</code>. The new version&#39;s file has the shipped keystore password, which does not open your keystore. With the wrong keystore password the server logs <code>Could not initialize security settings</code> and <code>Could not start web server</code>, then reports that it started, with no Administrator and no API</li><li>Leave the <code>version</code> line as it is. The server reads it at startup to decide which configuration migrations to run, then writes the new version into it</li><li>Add the keys the new version introduces, and change each default the release notes say changed wherever you want the new value</li><li>Do the same for <code>custom.vmoptions</code> and any other file the comparison shows</li></ol><h3 id="using-docker" tabindex="-1">Using Docker <a class="header-anchor" href="#using-docker" aria-label="Permalink to &quot;Using Docker&quot;">​</a></h3><p>No 4.6.0 or 4.7.0 container image is published. The <code>openintegrationengine/engine</code> repository on Docker Hub has a single tag, <code>latest</code>, which is the 4.5.2-tp.1 technology preview. The 4.7.0 release notes describe a Docker build inside the engine repository instead, and say they &quot;do not announce a new published image or registry tag&quot;.</p><h2 id="after-the-upgrade" tabindex="-1">After the upgrade <a class="header-anchor" href="#after-the-upgrade" aria-label="Permalink to &quot;After the upgrade&quot;">​</a></h2><h3 id="_1-verify-server-startup" tabindex="-1">1. Verify server startup <a class="header-anchor" href="#_1-verify-server-startup" aria-label="Permalink to &quot;1. Verify server startup&quot;">​</a></h3><p>Check the server logs (<code>logs/mirth.log</code>) for:</p><ul><li>Successful startup messages</li><li>Database migration completion</li><li>Extension loading</li><li>Any errors or warnings</li></ul><h3 id="_2-check-database-tasks" tabindex="-1">2. Check Database Tasks <a class="header-anchor" href="#_2-check-database-tasks" aria-label="Permalink to &quot;2. Check Database Tasks&quot;">​</a></h3><p>Navigate to <strong>Settings &gt; Database Tasks</strong> in the Administrator. The tasks it can list remove tables left over from upgrades of 2.x and pre-3.3 servers, and add a metadata index used by queues. An upgrade from 4.6.0 adds none. If the list is empty there is nothing to run.</p><ul><li>These tasks are <strong>not</strong> run automatically. Select a task row and click <strong>Run Task</strong> in the task panel on the left. A task can be cancelled with <strong>Cancel Task</strong></li><li><strong>Add Metadata Index</strong> creates the index only on channels that are stopped</li><li>Tasks may take a long time on large databases; monitor progress via the Status column and server logs</li></ul><h3 id="_3-verify-channels" tabindex="-1">3. Verify channels <a class="header-anchor" href="#_3-verify-channels" aria-label="Permalink to &quot;3. Verify channels&quot;">​</a></h3><ol><li>Check that all channels are in their expected state (deployed/undeployed)</li><li>Start channels and verify message processing</li><li>Check the Message Browser for any errors</li><li>Test critical interfaces end-to-end</li></ol><h3 id="_4-verify-extensions" tabindex="-1">4. Verify extensions <a class="header-anchor" href="#_4-verify-extensions" aria-label="Permalink to &quot;4. Verify extensions&quot;">​</a></h3><p>Check <strong>Extensions</strong> in the Administrator to ensure all plugins and connectors loaded correctly. An extension built for an earlier version is not loaded; check the server log for errors and install updated versions.</p><h2 id="rollback-plan" tabindex="-1">Rollback plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback plan&quot;">​</a></h2><p>If the upgrade fails:</p><ol><li>Stop the server</li><li>Restore from your backup: <ul><li>Replace the installation directory with the backup</li><li>Restore the database from backup (if using an external database) or restore the <code>appdata/mirthdb</code> folder (if using embedded Derby)</li><li>Restore <code>conf/mirth.properties</code> and any other customized configuration files</li></ul></li><li>Start the old version</li></ol><p>You can also restore a server configuration backup via the Administrator (<strong>Settings &gt; Server Tab &gt; Server Tasks &gt; Restore Config</strong>). It overwrites all current channels, alerts, code templates, server properties, global scripts, and plugin properties. Its confirmation dialog has two options: <strong>Deploy all channels after import</strong>, ticked by default, and <strong>Overwrite Configuration Map</strong>, unticked by default, so the configuration map is restored only if you tick it.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Once the new version has started on a database, the old version cannot use it. 4.6.0 started on a database that 4.7.0 has used logs <code>Failed to migrate database schema</code> and does not start. Restore the database from your backup before starting the old version.</p></div><h2 id="common-upgrade-issues" tabindex="-1">Common upgrade issues <a class="header-anchor" href="#common-upgrade-issues" aria-label="Permalink to &quot;Common upgrade issues&quot;">​</a></h2><h3 id="java-version-mismatch" tabindex="-1">Java version mismatch <a class="header-anchor" href="#java-version-mismatch" aria-label="Permalink to &quot;Java version mismatch&quot;">​</a></h3><p>Newer OIE versions may require a newer Java version. Check the release notes for the minimum Java requirement and update Java before upgrading.</p><h2 id="version-specific-notes" tabindex="-1">Version-specific notes <a class="header-anchor" href="#version-specific-notes" aria-label="Permalink to &quot;Version-specific notes&quot;">​</a></h2><h3 id="upgrading-to-4-7-0" tabindex="-1">Upgrading to 4.7.0 <a class="header-anchor" href="#upgrading-to-4-7-0" aria-label="Permalink to &quot;Upgrading to 4.7.0&quot;">​</a></h3><p>The 4.7.0 release notes list their breaking changes under <strong>Breaking changes and upgrade considerations</strong>; read that section in full. These are the ones that affect an existing installation:</p><p><strong>An older engine cannot use the upgraded database.</strong> After 4.7.0 has started on a database, 4.6.0 fails at startup with <code>Failed to migrate database schema</code>. Going back means restoring the database backup; see <a href="#rollback-plan">Rollback plan</a>.</p><p><strong>Your configuration keeps its old password policy.</strong> A new 4.7.0 <code>conf/mirth.properties</code> sets <code>password.minlength = 15</code>, <code>password.retrylimit = 100</code> and <code>password.lockoutperiod = 1</code>, where 4.6.0 shipped <code>0</code> for all three. An upgraded installation keeps its own values until you merge the new ones. See <a href="./user_management.html#password-policy">Password policy</a>.</p><p><strong>The generated admin password applies to new databases only.</strong> The new <code>server.initialadminpassword</code> key, and the password 4.7.0 generates when it is blank, are used only when the database is first created. An upgraded database keeps its users and their passwords. See <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a>.</p><p><strong>If you started 4.6.0 with <code>oieserver.ps1</code>, pin Java another way.</strong> 4.7.0 no longer ships <code>oieserver.ps1</code>, and the Linux installer removes it on upgrade. The <code>oieserver</code> launcher in installs and archives is generated by install4j. It ignores <code>OIE_JAVA_PATH</code>, and a <code>-java-cmd</code> line in <code>conf/custom.vmoptions</code> stops it from starting, so remove that line and pin a Java with <code>-jvm=</code> instead. <code>JAVA_HOME</code> is ignored when a <code>java</code> is on the <code>PATH</code>. See <a href="./server_process_management.html#choosing-a-java">Choosing a Java</a>.</p><p><strong>The bundled Java is 21.</strong> The with-JRE installers bundle Eclipse Temurin JDK 21.0.12.1 in place of Azul Zulu 17. See <a href="./installation.html#choosing-an-installer">Choosing an installer</a>. On Java 21 the Web Service Listener fails every SOAP request; see <a href="./connector_reference_sources.html#web-service-listener">Web Service Listener</a>.</p><p><strong>Extensions need a 4.7.0 build.</strong> An extension whose <code>&lt;mirthVersion&gt;</code> does not list <code>4.7.0</code> is not loaded. See <a href="./plugins.html#plugin-compatibility-and-version-requirements">Plugin compatibility and version requirements</a>.</p><p><strong>Two script behaviors changed.</strong> A preprocessor, global or channel, that ends without <code>return</code> now leaves the message unchanged, where 4.6.0 replaced the message with the text <code>undefined</code>. In the postprocessor, <code>channelName</code> now holds the channel&#39;s name, where 4.6.0 left it null. See <a href="./global_scripts.html#global-preprocessor-script">Global preprocessor script</a>.</p><p><strong>The extension launch descriptor endpoint is gone.</strong> <code>/webstart/extensions/&lt;extension&gt;.jnlp</code> now answers 404; extension resources are listed in the main launch descriptor, <code>/webstart.jnlp</code>. A custom launcher that fetched the per-extension descriptors needs updating.</p><p>The release notes also list these, which apply only if you use the feature named:</p><ul><li><strong>SQL Server through the Microsoft driver</strong>: the bundled driver moves from 8.4.1 to 10.2.4, which encrypts connections by default. An engine whose own database is on SQL Server through this driver stops at startup with <code>PKIX path building failed</code> unless the server&#39;s certificate is trusted by the Java runtime; adding <code>;trustServerCertificate=true</code> to <code>database.url</code> lets it start but skips certificate validation. Channel connections through the driver are affected the same way</li><li><strong>XML with a DOCTYPE</strong>: DOCTYPE declarations are rejected in source XML passed to XSLT steps, XML batch splitting, and the strict HL7 v2 XML parser</li><li><strong>HTTP Listener</strong>: the new request-header-size setting keeps the 8192-byte limit for existing channels; a value that is not a positive integer stops the connector from starting</li><li><strong>Custom metadata filters</strong> in API calls must name configured columns exactly</li><li><strong><code>selectLimit</code></strong> in Database Drivers settings and <code>dbdrivers.xml</code>, and the <code>selectLimit</code> parameter of <code>POST /connectors/jdbc/_getTables</code>, are ignored</li><li><strong>The Administrator</strong> checks for JavaFX at startup and stops with a message when the <code>javafx.graphics</code> module is missing</li><li><strong>The CLI</strong> returns nonzero exit codes for startup failures (authentication, connection, configuration, usage, unreadable script). This does not cover every failed command inside a script</li><li><strong>JSON</strong> handled through Jackson has new parsing limits on nesting depth and token length</li><li><strong>Custom Java code</strong>: <code>EngineController</code> adds an abstract <code>dispatchRawMessage</code> overload and <code>MessageServletInterface</code> adds <code>processBatchMessage</code>; the release notes list further API changes</li><li><strong>Source builds</strong> use Gradle instead of Ant; see <a href="./building_from_source.html">Building from Source</a></li></ul><h3 id="upgrading-to-4-6-0" tabindex="-1">Upgrading to 4.6.0 <a class="header-anchor" href="#upgrading-to-4-6-0" aria-label="Permalink to &quot;Upgrading to 4.6.0&quot;">​</a></h3><p>The 4.6.0 release notes list four changes that can break a working installation or change behavior silently.</p><p><strong>Java 17 is the minimum.</strong> Older JVMs are no longer supported. The release notes say later Java LTS releases should work but are not officially tested, so a server pinned to Java 11 needs its runtime updated first.</p><p><strong>Xerces and xml-apis have been removed.</strong> Custom code that imports <code>org.apache.xerces.*</code> directly will fail to load. Migrate those imports to <code>javax.xml.parsers.*</code> and <code>org.xml.sax.*</code>. This affects code templates, channel scripts, and custom extensions alike. Search your scripts for the old package before you upgrade.</p><p><strong>Logins are case-insensitive by default.</strong> <code>admin</code>, <code>Admin</code>, and <code>ADMIN</code> now resolve to the same account. Existing accounts with case-sensitive usernames continue to work through a compatibility path.</p><p><strong>HTTP parameter map ordering is now preserved.</strong> Previously the order was non-deterministic. A script that depends on the old ordering may behave differently.</p><p>Two operational notes from the same release notes:</p><ul><li>Installers remove the prior release as part of the upgrade, preserving the directories that must survive it, including <code>appdata</code>, <code>conf</code>, <code>extensions</code>, and <code>logs</code>.</li><li>The release remediates 24 known CVEs (1 critical, 10 high, 12 medium, 1 low) through dependency upgrades.</li></ul><p>The full release notes, including the complete dependency and CVE list, are published with the <a href="https://github.com/OpenIntegrationEngine/engine/releases/tag/v4.6.0" target="_blank" rel="noreferrer">v4.6.0 release</a>.</p>',62)]))}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
